/* ---------- camera ---------- */
function clampCam() {
  const halfW = W / (2 * G.cam.z), halfH = H / (2 * G.cam.z), m = 40;
  if (MAP.pw < halfW * 2 + m * 2) G.cam.x = MAP.pw / 2;
