+}
+
+function orderMove(list, gx, gy, type = 'move') {
+  if (!list.length) return;
+  gx = clamp(gx, 1.2, MAP.w - 1.2); gy = clamp(gy, 1.2, MAP.h - 1.2);
+  const n = list.length;
