  lastTap = { t:now, x:sx, y:sy };
  if (G.targetMode) { resolveTarget(sx, sy); return; }
  if (ent) {
    if (STATS[ent.kind]) {
      if (ent.team === 'player') selectUnits([ent.id]);
      else if (selectedUnits().length) orderAttack(selectedUnits(), ent);
      else inspectEntity(ent);
