+    }
+    if (!target && u.order && u.order.type === 'attack') { u.order = null; }
+    if (target && !u.order && dist(u, target) > 11) target = null;
+
+    if (target) {
+      const d = dist(u, target) - target.radius * .55;
+      faceTarget(u, target);
+      if (d <= st.range) {
