  sun.addColorStop(0, 'rgba(255,225,170,.34)'); sun.addColorStop(.35, 'rgba(238,186,112,.1)'); sun.addColorStop(1, 'rgba(238,186,112,0)');
  ctx.fillStyle = sun; ctx.fillRect(0, 0, W, H);
  const shift = -(G.cam.x / MAP.pw - .5) * 70;
