    ctx.strokeStyle = 'rgba(64,61,52,.48)'; ctx.lineWidth = 1.4 * s;
    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y + 36 * s); ctx.stroke();
