  }
}
function drawWind(t) {
  ctx.save();
  for (let i = 0; i < 18; i++) {
    const speed = 26 + (i % 4) * 13;
    const x = ((i * 149 + t * speed) % (W + 240)) - 120;
    const y = (i * 71 + (i % 3) * 23) % (H * .82) + 20;
    const len = 24 + (i % 5) * 13;
    ctx.strokeStyle = `rgba(244,229,189,${.035 + (i % 3) * .014})`;
