const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const fs = require('fs');
(async () => {
  fs.mkdirSync('/home/runner/work/PlayGround/PlayGround/shots', { recursive: true });
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 }, deviceScaleFactor: 2,
    isMobile: true, hasTouch: true, userAgent: 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 Chrome/131 Mobile Safari/537.36'
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/01-start.jpg', type: 'jpeg', quality: 78 });

  await page.tap('#startBtn');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/02-game.jpg', type: 'jpeg', quality: 78 });
  const state1 = await page.evaluate(() => ({
    state: OXIDO.G.state, units: OXIDO.units.length, selected: OXIDO.G.sel.length,
    cam: {...OXIDO.G.cam}, pop: document.querySelector('#rPop').textContent,
    oil: document.querySelector('#rOil').textContent,
    dock: document.querySelector('.dockCard').getBoundingClientRect().height,
    minimap: document.querySelector('#minimapWrap').getBoundingClientRect()
  }));

  // Tap own base to open production
  const basePos = await page.evaluate(() => { const p = OXIDO.screenOf(OXIDO.base()); return {x:p.x,y:p.y}; });
  await page.touchscreen.tap(basePos.x, basePos.y);
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/03-base.jpg', type: 'jpeg', quality: 78 });
  const baseState = await page.evaluate(() => ({
    selectedBuilding: OXIDO.G.selBuilding && OXIDO.G.selBuilding.kind,
    cards: [...document.querySelectorAll('[data-prod]')].map(b => ({k:b.dataset.prod, disabled:b.disabled})),
    dock: document.querySelector('.dockCard').getBoundingClientRect().height
  }));

  // Build a tirador via UI
  const beforeOil = await page.evaluate(() => OXIDO.G.oil);
  const card = page.locator('[data-prod="tirador"]');
  await card.tap();
  await page.waitForTimeout(400);
  const prodState = await page.evaluate(() => ({ queue: OXIDO.G.queue.map(q => q.kind), oil: OXIDO.G.oil, html: document.querySelector('.queue').textContent.trim() }));
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/04-prod.jpg', type: 'jpeg', quality: 78 });

  // long press on map to open radial
  await page.mouse.move(190, 380);
  await page.mouse.down();
  await page.waitForTimeout(620);
  await page.mouse.up();
  await page.waitForTimeout(250);
  const radial = await page.evaluate(() => document.querySelector('#radial').classList.contains('show'));
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/05-radial.jpg', type: 'jpeg', quality: 78 });
  await page.evaluate(() => document.querySelector('#radialClose').click());

  // select army and move via tap
  await page.evaluate(() => OXIDO.selectAll());
  const unitPos = await page.evaluate(() => { const u = OXIDO.units.find(u=>u.team==='player'); const p=OXIDO.screenOf(u); return p; });
  await page.touchscreen.tap(220, 520);
  await page.waitForTimeout(900);
  const moveState = await page.evaluate(() => OXIDO.units.filter(u=>u.team==='player').slice(0,3).map(u => ({x:+u.x.toFixed(2),y:+u.y.toFixed(2),order:u.order && u.order.type})));

  console.log(JSON.stringify({ state1, baseState, beforeOil, prodState, radial, moveState, errors }, null, 2));
  await browser.close();
})();

