const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless:true, args:['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport:{width:390,height:844}, deviceScaleFactor:2, isMobile:true, hasTouch:true });
  const page = await ctx.newPage();
  const logs=[]; page.on('pageerror',e=>logs.push(String(e)));
  await page.goto('http://localhost:3002/', {waitUntil:'networkidle'});
  await page.waitForTimeout(300);
  await page.tap('#startBtn');
  await page.waitForTimeout(700);
  const out = await page.evaluate(() => {
    OXIDO.G.state='paused';
    const c = document.querySelector('#game');
    const g = c.getContext('2d');
    g.setTransform(2,0,0,2,0,0);
    const pts = OXIDO.units.filter(u=>u.team==='player').map(u=>{const p=OXIDO.screenOf(u); g.fillStyle='#ff00ff'; g.fillRect(p.x-3,p.y-3,6,6); return p;});
    return { sel:OXIDO.G.sel.slice(), dock:document.querySelector('#dockInfo').textContent.replace(/\s+/g,' ').trim(), pts };
  });
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/shots/07-marker.jpg',type:'jpeg',quality:85});
  console.log(JSON.stringify({out,logs},null,2));
  await browser.close();
})();

