const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 }, deviceScaleFactor: 2,
    isMobile: true, hasTouch: true,
    userAgent: 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 Chrome/131 Mobile Safari/537.36'
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });

  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.tap('#startBtn');
  await page.waitForTimeout(700);

  // Pause overlay
  await page.tap('#btnPause');
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/10-pause.jpg', type: 'jpeg', quality: 82 });
  const pauseState = await page.evaluate(() => ({
    state: OXIDO.G.state,
    overlay: document.querySelector('#pauseScreen').classList.contains('show')
  }));
  await page.tap('#resumeBtn');
  await page.waitForTimeout(300);

  // Force a wave and let combat resolve at 2x
  const waveBefore = await page.evaluate(() => {
    OXIDO.G.waveTimer = 0; OXIDO.G.speed = 2;
    return { wave: OXIDO.G.wave, enemies: OXIDO.units.filter(u => u.team === 'enemy').length };
  });
  await page.waitForTimeout(2500);
  const waveAfter = await page.evaluate(() => ({
    wave: OXIDO.G.wave,
    enemies: OXIDO.units.filter(u => u.team === 'enemy').length,
    time: +OXIDO.G.time.toFixed(1),
    alerts: document.querySelectorAll('#alerts .alert').length
  }));

  // Capture the antenna: teleport player infantry next to it and wait
  const cap = await page.evaluate(async () => {
    const ant = OXIDO.buildings.find(b => b.kind === 'antenna');
    const squad = OXIDO.units.filter(u => u.team === 'player' && u.kind !== 'mecanico').slice(0, 3);
    squad.forEach((u, i) => { u.x = ant.x + 1.1 + i * 0.35; u.y = ant.y + 0.6; u.order = null; });
    OXIDO.G.speed = 3;
    const start = ant.team;
    return { start, cap: ant.capture, squad: squad.length };
  });
  await page.waitForTimeout(6000);
  const capAfter = await page.evaluate(() => {
    const ant = OXIDO.buildings.find(b => b.kind === 'antenna');
    return { team: ant.team, capture: +ant.capture.toFixed(2), toast: document.querySelector('#miniOwner').textContent };
  });
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/11-capture.jpg', type: 'jpeg', quality: 82 });

  // Combat: spawn enemy next to squad and let it fight
  const combat = await page.evaluate(() => {
    const u = OXIDO.units.find(x => x.team === 'player');
    const p = OXIDO.screenOf(u);
    OXIDO.spawnWave();
    return { px: p.x, py: p.y, enemies: OXIDO.units.filter(x => x.team === 'enemy').length };
  });
  await page.waitForTimeout(3000);
  const combatAfter = await page.evaluate(() => ({
    kills: OXIDO.G.kills,
    scraps: OXIDO.scraps.length,
    enemies: OXIDO.units.filter(x => x.team === 'enemy').length,
    players: OXIDO.units.filter(x => x.team === 'player').length
  }));

  // Win screen
  await page.evaluate(() => { OXIDO.G.speed = 3; OXIDO.forceWin(); });
  await page.waitForTimeout(2500);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/12-win.jpg', type: 'jpeg', quality: 82 });
  const winState = await page.evaluate(() => ({
    state: OXIDO.G.state,
    end: document.querySelector('#endScreen').classList.contains('show'),
    title: document.querySelector('#endTitle').textContent,
    stats: document.querySelector('#endStats').textContent.replace(/\s+/g, ' ').trim()
  }));

  // Defeat screen on a fresh load
  const page2 = await context.newPage();
  page2.on('pageerror', e => errors.push('P2 PAGEERROR ' + e.message));
  await page2.goto('http://localhost:3002/?play=1', { waitUntil: 'networkidle' });
  await page2.waitForTimeout(1200);
  const defeat = await page2.evaluate(() => {
    const ref = OXIDO.buildings.find(b => b.kind === 'refinery');
    ref.hp = 0.01;
    const enemy = { team: 'enemy', x: ref.x, y: ref.y, id: -99, radius: 1 };
    // force destruction through simulation path
    ref.hp = 0;
    OXIDO.G.pendingEnd = { win: false, t: 0.1 };
    return { hp: ref.hp };
  });
  await page2.waitForTimeout(2000);
  await page2.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/13-defeat.jpg', type: 'jpeg', quality: 82 });
  const defeatState = await page2.evaluate(() => ({
    state: OXIDO.G.state,
    show: document.querySelector('#endScreen').classList.contains('show'),
    title: document.querySelector('#endTitle').textContent
  }));

  console.log(JSON.stringify({ pauseState, waveBefore, waveAfter, cap, capAfter, combat, combatAfter, winState, defeatState, errors }, null, 2));
  await browser.close();
})();

