(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const results = {};
  for (const vp of [{ name: 'portrait', width: 390, height: 844 }, { name: 'landscape', width: 844, height: 390 }]) {
    const context = await browser.newContext({
      viewport: { width: vp.width, height: vp.height }, deviceScaleFactor: 2,
      isMobile: true, hasTouch: true,
      userAgent: 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 Chrome/131 Mobile Safari/537.36'
    });
    const page = await context.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
    await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
    await page.waitForTimeout(500);
    await page.tap('#startBtn');
    await page.waitForTimeout(900);

    // Select army, tap the topbar area, ensure no orders were issued
    await page.evaluate(() => { OXIDO.selectAll(); OXIDO.units.forEach(u => u.order = null); });
    await page.touchscreen.tap(24, 18);
    await page.waitForTimeout(200);
    const afterTopTap = await page.evaluate(() => OXIDO.units.filter(u => u.team === 'player' && u.order).length);
    await page.evaluate(() => { OXIDO.units.forEach(u => u.order = null); });
    await page.touchscreen.tap(Math.round(vp.width * 0.5), Math.round(vp.height * 0.45));
    await page.waitForTimeout(250);
    const afterMapTap = await page.evaluate(() => OXIDO.units.filter(u => u.team === 'player' && u.order).length);

    const layout = await page.evaluate(() => {
      const box = sel => { const b = document.querySelector(sel).getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) }; };
      return { top: box('#topbar'), info: box('#infoRow'), mini: box('#minimapWrap'), dock: box('#dock'), body: document.body.className };
    });

    results[vp.name] = { afterTopTap, afterMapTap, layout, errors };
    await page.screenshot({ path: `/home/runner/work/PlayGround/PlayGround/shots/30-final-${vp.name}.jpg`, type: 'jpeg', quality: 82 });
    await context.close();
  }
  console.log(JSON.stringify(results, null, 2));
  await browser.close();
})();

