const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 }, deviceScaleFactor: 2,
    isMobile: true, hasTouch: true,
    userAgent: 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 Chrome/131 Mobile Safari/537.36'
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.tap('#startBtn');
  await page.waitForTimeout(800);

  // Teleport squad to the nest, start an assault and spawn a wave next to it
  const setup = await page.evaluate(() => {
    const n = OXIDO.nest();
    const squad = OXIDO.units.filter(u => u.team === 'player');
    squad.forEach((u, i) => {
      u.x = n.x - 4 + i * 0.9; u.y = n.y - 2.5 + (i % 2) * 1.4;
      u.maxHp *= 1.3; u.hp = u.maxHp; u.kills = i === 0 ? 6 : i === 1 ? 3 : 1;
      u.order = { type: 'attack', targetId: n.id };
    });
    OXIDO.selectAll();
    OXIDO.G.speed = 1;
    OXIDO.centerOn = OXIDO.centerOn || (() => {});
    return { nest: { x: n.x, y: n.y }, squad: squad.length };
  });

  // Center camera on the fight through the exposed camera object
  await page.evaluate(() => {
    const n = OXIDO.nest();
    const p = OXIDO.screenOf(n);
    // move camera so the nest is centered above the dock
    OXIDO.G.cam.x += (p.x - 195) / OXIDO.G.cam.z;
    OXIDO.G.cam.y += (p.y - 340) / OXIDO.G.cam.z;
  });
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/40-combat.jpg', type: 'jpeg', quality: 86 });

  await page.waitForTimeout(2200);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/41-combat2.jpg', type: 'jpeg', quality: 86 });
  const fight = await page.evaluate(() => ({
    nestHp: Math.round(OXIDO.nest() ? OXIDO.nest().hp : 0),
    kills: OXIDO.G.kills,
    scraps: OXIDO.scraps.length,
    effects: OXIDO.G.state,
    ranks: OXIDO.units.filter(u => u.team === 'player').map(u => u.rank),
    enemies: OXIDO.units.filter(u => u.team === 'enemy').length,
    alarm: document.querySelector('#alerts .alert')?.textContent || null
  }));

  // Check HUD minimum touch targets
  const targets = await page.evaluate(() => {
    const sel = ['#btnSound', '#btnPause', '#startBtn', '.closeSel'];
    return sel.map(s => {
      const el = document.querySelector(s);
      if (!el) return { s, missing: true };
      const r = el.getBoundingClientRect();
      return { s, w: Math.round(r.width), h: Math.round(r.height) };
    });
  });

  console.log(JSON.stringify({ setup, fight, targets, errors }, null, 2));
  await browser.close();
})();

