const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 }, deviceScaleFactor: 2,
    isMobile: true, hasTouch: true
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  await page.tap('#startBtn');
  await page.waitForTimeout(800);

  const pe = (type, id, x, y) => page.evaluate(([type, id, x, y]) => {
    const cv = document.querySelector('#game');
    const ev = new PointerEvent(type, {
      pointerId: id, pointerType: 'touch', isPrimary: id === 1,
      clientX: x, clientY: y, bubbles: true, cancelable: true, buttons: type === 'pointerup' ? 0 : 1
    });
    cv.dispatchEvent(ev);
  }, [type, id, x, y]);

  // --- box selection over the units ---
  await page.evaluate(() => { OXIDO.G.sel = []; document.querySelector('[data-util="close"]')?.click(); });
  await page.waitForTimeout(200);
  const ups = await page.evaluate(() => OXIDO.units.filter(u => u.team === 'player').map(u => OXIDO.screenOf(u)));
  const minX = Math.min(...ups.map(p => p.x)) - 30, maxX = Math.max(...ups.map(p => p.x)) + 30;
  const minY = Math.min(...ups.map(p => p.y)) - 45, maxY = Math.max(...ups.map(p => p.y)) + 20;
  await pe('pointerdown', 1, minX, minY);
  await page.waitForTimeout(60);
  await pe('pointermove', 1, (minX + maxX) / 2, (minY + maxY) / 2);
  await page.waitForTimeout(60);
  await pe('pointermove', 1, maxX, maxY);
  await page.waitForTimeout(60);
  await pe('pointerup', 1, maxX, maxY);
  await page.waitForTimeout(300);
  const boxSel = await page.evaluate(() => OXIDO.G.sel.length);

  // --- two-finger pinch zoom ---
  const z0 = await page.evaluate(() => OXIDO.G.cam.z);
  await pe('pointerdown', 1, 140, 420);
  await page.waitForTimeout(40);
  await pe('pointerdown', 2, 250, 420);
  await page.waitForTimeout(40);
  await pe('pointermove', 2, 310, 420);
  await page.waitForTimeout(80);
  await pe('pointermove', 2, 350, 420);
  await page.waitForTimeout(80);
  const z1 = await page.evaluate(() => OXIDO.G.cam.z);
  await pe('pointerup', 2, 350, 420);
  await pe('pointerup', 1, 140, 420);
  await page.waitForTimeout(120);

  // --- long press opens radial ---
  await page.evaluate(() => OXIDO.selectAll());
  await pe('pointerdown', 3, 300, 300);
  await page.waitForTimeout(620);
  const radialOpen = await page.evaluate(() => document.querySelector('#radial').classList.contains('show'));
  await pe('pointerup', 3, 300, 300);
  await page.waitForTimeout(150);
  await pe('pointerdown', 4, 300, 300);
  await pe('pointerup', 4, 300, 300);
  await page.waitForTimeout(150);
  const radialAfterTapOutside = await page.evaluate(() => document.querySelector('#radial').classList.contains('show'));

  // --- minimap navigation ---
  const cam0 = await page.evaluate(() => ({ x: Math.round(OXIDO.G.cam.x), y: Math.round(OXIDO.G.cam.y) }));
  const mini = await page.evaluate(() => { const r = document.querySelector('#minimap').getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height }; });
  await page.touchscreen.tap(mini.x + mini.w * 0.8, mini.y + mini.h * 0.85);
  await page.waitForTimeout(300);
  const cam1 = await page.evaluate(() => ({ x: Math.round(OXIDO.G.cam.x), y: Math.round(OXIDO.G.cam.y) }));

  console.log(JSON.stringify({ boxSel, zoom: { z0: +z0.toFixed(3), z1: +z1.toFixed(3) }, radialOpen, radialAfterTapOutside, cam0, cam1, errors }, null, 2));
  await browser.close();
})();

