const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const errors = [];

  async function makePage() {
    const ctx = await browser.newContext({
      viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true
    });
    const p = await ctx.newPage();
    p.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
    p.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
    await p.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
    await p.waitForTimeout(400);
    await p.tap('#startBtn');
    await p.waitForTimeout(700);
    return p;
  }

  // --- A: idle player, natural defeat ---
  const a = await makePage();
  await a.evaluate(() => {
    OXIDO.G.speed = 3;
    // Incompetent commander: keep units at home but they will still defend.
  });
  await a.waitForTimeout(60000);
  const idle = await a.evaluate(() => ({
    state: OXIDO.G.state,
    time: Math.round(OXIDO.G.time),
    wave: OXIDO.G.wave,
    refinery: OXIDO.base() ? Math.round(OXIDO.base().hp) : null,
    enemies: OXIDO.units.filter(u => u.team === 'enemy').length,
    players: OXIDO.units.filter(u => u.team === 'player').length,
    endTitle: document.querySelector('#endTitle').textContent,
    endShown: document.querySelector('#endScreen').classList.contains('show')
  }));
  await a.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/60-idle.jpg', type: 'jpeg', quality: 82 });

  // --- B: strong squad assaults the nest for real ---
  const b = await makePage();
  await b.evaluate(() => {
    const n = OXIDO.nest();
    for (let i = 0; i < 8; i++) {
      const u = OXIDO.units.find(x => x.team === 'player' && x.kind === 'tirador') || OXIDO.units.find(x => x.team === 'player');
      const kind = i % 3 === 0 ? 'lanzachatarra' : 'tirador';
      const st = window.OXIDO;
      // spawn via production-free helper: reuse spawnWave? not for player; emulate through OXIDO.make needs base.
    }
    // Use the production pipeline: select base, queue 8 lanzachatarra with free oil
    OXIDO.G.oil = 9999; OXIDO.G.cap = 40;
    const base = OXIDO.base();
    OXIDO.G.sel = []; OXIDO.G.selBuilding = base;
    for (let i = 0; i < 8; i++) OXIDO.make(i % 2 ? 'lanzachatarra' : 'tirador');
  });
  await b.waitForTimeout(20000); // build queue at 3x
  await b.evaluate(() => {
    const n = OXIDO.nest();
    OXIDO.selectAll();
    OXIDO.units.filter(u => u.team === 'player').forEach((u, i) => {
      u.x = n.x - 3.2 + (i % 4) * 0.9; u.y = n.y - 2.6 + Math.floor(i / 4) * 1.3;
      u.order = { type: 'attack', targetId: n.id };
    });
    const p = OXIDO.screenOf(n);
    OXIDO.G.cam.x += (p.x - 195) / OXIDO.G.cam.z;
    OXIDO.G.cam.y += (p.y - 330) / OXIDO.G.cam.z;
    OXIDO.G.speed = 3;
  });
  await b.waitForTimeout(12000);
  const assault = await b.evaluate(() => ({
    state: OXIDO.G.state,
    nestHp: OXIDO.nest() ? Math.round(OXIDO.nest().hp) : 'destruido',
    kills: OXIDO.G.kills,
    squad: OXIDO.units.filter(u => u.team === 'player').length,
    endTitle: document.querySelector('#endTitle').textContent,
    endShown: document.querySelector('#endScreen').classList.contains('show')
  }));
  await b.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/61-assault.jpg', type: 'jpeg', quality: 82 });

  console.log(JSON.stringify({ idle, assault, errors }, null, 2));
  await browser.close();
})();

